const poems=window.poems;const index=document.getElementById('poem-index');function list(q=''){index.replaceChildren();poems.filter(p=>p.title.toLowerCase().includes(q.toLowerCase())).forEach(p=>{const a=document.createElement('a');a.href='#'+p.id;a.textContent=p.title;a.dataset.id=p.id;index.append(a)});mark()}function mark(){index.querySelectorAll('a').forEach(a=>a.setAttribute('aria-current',String(a.dataset.id===(location.hash.slice(1)||poems[0].id))))}function show(){let i=poems.findIndex(p=>p.id===location.hash.slice(1));if(i<0)i=0;const p=poems[i];document.getElementById('poem-title').textContent=p.title;document.getElementById('poem-body').textContent=p.lines.join('\n');document.getElementById('poem-number').textContent=String(i+1).padStart(2,'0')+' / '+poems.length+' · BHOOMI KOTHARI';document.title=p.title+' · Bhoomi’s poetry';for(const [id,n] of [['prev',i-1],['next',i+1]]){const a=document.getElementById(id);a.hidden=n<0||n>=poems.length;if(!a.hidden)a.href='#'+poems[n].id}mark()}document.getElementById('poem-search').addEventListener('input',e=>list(e.target.value));window.addEventListener('hashchange',()=>{show();document.getElementById('poem-title').focus({preventScroll:true});document.getElementById('reading').scrollIntoView({block:'start'})});list();show();